 const feminine={'عليك':'عَلَيْكِ','حالك':'حالُكِ','فهمت':'فَهِمْتِ','انهيت':'أَنْهَيْتِ','عملك':'عَمَلَكِ','ردك':'رَدُّكِ','صوتك':'صَوْتُكِ','تسجيلك':'تَسْجيلِكِ','اسمك':'اسْمُكِ','احسنت':'أَحْسَنْتِ','اكملت':'أَكْمَلْتِ','استمعي':'اِسْتَمِعي','اسمعي':'اِسْمَعي','اختاري':'اِخْتاري','اضغطي':'اِضْغَطي','سجلي':'سَجِّلي','اكتبي':'اُكْتُبي','راجعي':'راجِعي','حاولي':'حاوِلي','جربي':'جَرِّبي','تحدثي':'تَحَدَّثي','والعبي':'وَالْعَبي','تستطيعين':'تَسْتَطيعينَ','تحتاجين':'تَحْتاجينَ','تريدين':'تُريدينَ','تساعدينني':'تُساعِدينَني','معلمتي':'مُعَلِّمَتي'};
