function openPlace(index){if(busy()){setStatus('انتظري انتهاء التسجيل والتحويل.');return;}placeIndex=index;const p=places[index];lessons.splice(0,lessons.length,...p.lessons);$('placeTitle').textContent=p.icon+' '+p.name;$('adventureHome').hidden=true;$('classroom').hidden=false;const scene=document.querySelector('.classScene');scene.style.backgroundImage='url('+document.querySelector('.mapImage').src+')';scene.style.backgroundPosition=p.art;scene.querySelector('span').hidden=true;$('lessonCards').replaceChildren();lessons.forEach((l,i)=>{const b=document.createElement('button');b.textContent=l.icon+' '+l.title;b.onclick=()=>openLesson(i);$('lessonCards').append(b);});openLesson(0);}
places.forEach((p,i)=>{const b=document.createElement('button');b.textContent=p.icon+' '+p.name;b.onclick=()=>openPlace(i);$('placeButtons').append(b);});document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>openPlace(Number(b.dataset.place)));$('enterClass').onclick=()=>openPlace(0);$('mapClass').onclick=()=>openPlace(0);

let arabicVoices=[];
function preferArabicVoice(list){return list.find(v=>/hoda|salma|zariyah|laila|layla|fatima|amina|female|هدى|سلمى|ليلى|فاطمة/i.test(v.name))||list[0];}
function selectedArabicVoice(){const list=window.speechSynthesis?.getVoices().filter(v=>/^ar([-_]|$)/i.test(v.lang))||[];return list.find(v=>v.voiceURI===$('voiceChoice').value)||preferArabicVoice(list);}
function refreshArabicVoices(){const previous=$('voiceChoice').value;arabicVoices=window.speechSynthesis?.getVoices().filter(v=>/^ar([-_]|$)/i.test(v.lang))||[];$('voiceChoice').replaceChildren();const fixed=document.createElement('option');fixed.value='fixed-laila';fixed.textContent='ليلى — صوت عربي نسائي موحّد';$('voiceChoice').append(fixed);for(const v of arabicVoices){const option=document.createElement('option');option.value=v.voiceURI;option.textContent='صوت الجهاز: '+v.name+' — '+v.lang;$('voiceChoice').append(option);}$('voiceChoice').value=arabicVoices.some(v=>v.voiceURI===previous)?previous:'fixed-laila';}
window.speechSynthesis?.addEventListener('voiceschanged',refreshArabicVoices);
$('voiceSettings').onclick=()=>{$('voicePanel').hidden=!$('voicePanel').hidden;$('voiceSettings').setAttribute('aria-expanded',String(!$('voicePanel').hidden));refreshArabicVoices();};
$('testVoice').onclick=()=>say('السَّلامُ عَلَيْكِ يا صَديقَتي. كَيْفَ حالُكِ؟ أَحْسَنْتِ!');
refreshArabicVoices();

// Live browser recognition is an explicit alternative to the local model.
const SpeechEngine=window.SpeechRecognition||window.webkitSpeechRecognition;
let liveRecognition,liveText='',liveFailure=false,liveTimeout;
function updateSpeechMode(){
 if(recording||processing||pending)return;
 $('playback').hidden=true;
 $('record').textContent='🎙 تحدثي مباشرةً';
 $('modelStatus').textContent='بدون تنزيل نموذج. قد يرسل المتصفح الصوت إلى خدمة التعرف التابعة له؛ يتطلب الإنترنت. لا يُحفظ تسجيل للاستماع في هذا الوضع.';
 $('record').disabled=!SpeechEngine;
 setStatus(SpeechEngine?'جاهز للتجربة. اسمحي بالميكروفون ثم قولي جملة قصيرة.':'التحويل المباشر غير متاح هنا. جرّبي Safari على الآيفون أو Chrome على الكمبيوتر. يمكنك أيضًا استخدام ميكروفون لوحة المفاتيح في خانة النص.');
}
$('record').onclick=()=>{
 if(recording){liveRecognition?.stop();return;}
 if(processing||pending||modelLoading||!SpeechEngine)return;
 window.speechSynthesis?.cancel();stopFixedAudio();liveText='';liveFailure=false;
 $('response').value='';$('feedback').hidden=true;$('playback').hidden=true;
 const engine=new SpeechEngine();liveRecognition=engine;
 engine.lang='ar-SA';engine.continuous=false;engine.interimResults=true;engine.maxAlternatives=1;
 engine.onstart=()=>{pending=false;recording=true;$('record').disabled=false;$('check').disabled=true;$('response').disabled=true;$('record').textContent='■ انتهيتُ';start=Date.now();interval=setInterval(()=>{$('timer').textContent='00:'+String(Math.floor((Date.now()-start)/1000)).padStart(2,'0');},250);liveTimeout=setTimeout(()=>engine.stop(),20000);setStatus('أستمع إليكِ… قولي ردّكِ ثم توقّفي قليلًا.');};
 engine.onresult=e=>{let final='',interim='';for(let i=0;i<e.results.length;i++){if(e.results[i].isFinal)final+=e.results[i][0].transcript+' ';else interim+=e.results[i][0].transcript+' ';}if(final.trim())liveText=final.trim();$('response').value=(final+interim).trim();};
 engine.onerror=e=>{liveFailure=true;const messages={'not-allowed':'لم يُسمح بالتعرف الصوتي. تحققي من إذن الميكروفون وإعدادات الإملاء في الجهاز.','service-not-allowed':'خدمة التعرف الصوتي غير متاحة في هذا المتصفح. جرّبي Safari أو Chrome.','network':'تعذّر الاتصال بخدمة التعرف الصوتي. تحققي من الإنترنت.','no-speech':'لم أسمع كلامًا واضحًا. اقتربي من الميكروفون وحاولي مرة أخرى.','audio-capture':'لم يتوفر الميكروفون. أغلقي التطبيقات التي تستخدمه.','language-not-supported':'العربية غير متاحة في خدمة هذا المتصفح.'};showAudioError(messages[e.error]||'تعذّر التحويل المباشر ('+e.error+'). حاولي مرة أخرى أو استخدمي إملاء لوحة المفاتيح.');};
 engine.onend=()=>{pending=false;recording=false;clearInterval(interval);clearTimeout(liveTimeout);$('check').disabled=false;$('response').disabled=false;$('record').disabled=false;$('record').textContent='🎙 تحدثي مباشرةً';if(!liveFailure){if(liveText){$('response').value=liveText;check();setStatus('انتهى التحويل المباشر. راجعي الكلمات المكتوبة قبل اعتماد التصحيح.');}else showAudioError('لم يصل نص نهائي. حاولي مرة أخرى أو استخدمي ميكروفون لوحة المفاتيح.');}};
 try{pending=true;$('record').disabled=true;engine.start();}catch(e){pending=false;$('record').disabled=false;showAudioError('تعذّر بدء التحويل المباشر. أعيدي المحاولة.');}
};
