let fixedPlayer,fixedFinish;
function stopFixedAudio(){if(fixedPlayer){fixedPlayer.pause();fixedPlayer.removeAttribute('src');fixedPlayer=null;}if(fixedFinish){const finish=fixedFinish;fixedFinish=null;finish();}document.querySelectorAll('.speaking').forEach(x=>x.classList.remove('active','speaking'));}
function fixedAudioKey(text){return normalizeArabic(text).replace(/[🌟💛]/gu,'').replace(/\s+/g,' ').trim();}
function say(text,element){
 if(recording||pending)return Promise.resolve();
 stopFixedAudio();
 if($('voiceChoice').value!=='fixed-laila')return systemSay(text,element);
 window.speechSynthesis?.cancel();
 const src=fixedFemaleAudio[fixedAudioKey(text)];
 if(!src){$('audioNotice').textContent='الصوت النسائي لهذه العبارة غير متاح. يمكنكِ اختيار صوت الجهاز.';return Promise.resolve();}
 return new Promise(resolve=>{const player=new Audio(src);fixedPlayer=player;fixedFinish=()=>{element?.classList.remove('active','speaking');resolve();};if(element)element.classList.add('active','speaking');const finish=()=>{if(fixedPlayer===player){fixedPlayer=null;const done=fixedFinish;fixedFinish=null;done?.();}};player.onended=finish;player.onerror=()=>{$('audioNotice').textContent='تعذّر تشغيل الصوت. اضغطي زر الاستماع مرة أخرى.';finish();};player.play().catch(()=>{$('audioNotice').textContent='اضغطي زر الاستماع لتشغيل الصوت.';finish();});});
}
window.addEventListener('pagehide',stopFixedAudio);
$('voiceChoice').addEventListener('change',()=>{stopFixedAudio();window.speechSynthesis?.cancel();});

