 const h=column<2?160:188,cell=adventureRolesImage.naturalWidth/6,sh=adventureRolesImage.naturalHeight,w=h*cell/sh;
 c.drawImage(adventureRolesImage,column*cell,0,cell,sh,x-w/2,ground-h,w,h);
