function adventureGoldStar(c,x,y,size,now){c.save();c.translate(x,y+Math.sin(now/400+x)*3);c.shadowColor='rgba(255,218,76,.65)';c.shadowBlur=12;c.beginPath();for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,r=i%2?size*.46:size;i?c.lineTo(Math.cos(a)*r,Math.sin(a)*r):c.moveTo(Math.cos(a)*r,Math.sin(a)*r);}c.closePath();const g=c.createLinearGradient(-size,-size,size,size);g.addColorStop(0,'#fff7bf');g.addColorStop(.35,'#ffdf61');g.addColorStop(.7,'#d68d11');g.addColorStop(1,'#fff0a4');c.fillStyle=g;c.fill();c.shadowBlur=0;c.strokeStyle='#a86d15';c.lineWidth=1.3;c.stroke();c.restore();}
function adventureDrawPerson(c,column,x,ground,height,flip=false){if(!adventureCastImage.complete||!adventureCastImage.naturalWidth)return;const cell=adventureCastImage.naturalWidth/4;const sourceHeight=adventureCastImage.naturalHeight;const width=height*cell/sourceHeight;c.save();c.translate(x,ground);if(flip)c.scale(-1,1);c.drawImage(adventureCastImage,column*cell,0,cell,sourceHeight,-width/2,-height,width,height);c.restore();}
function renderAdventureArt(c,now){c.clearRect(0,0,960,420);if(adventurePlacesImage.complete&&adventurePlacesImage.naturalWidth){const w=adventurePlacesImage.naturalWidth/2,h=adventurePlacesImage.naturalHeight/4;c.drawImage(adventurePlacesImage,(placeIndex%2)*w,Math.floor(placeIndex/2)*h,w,h,0,0,960,420);}else{c.fillStyle='#e6d4b5';c.fillRect(0,0,960,420);c.fillStyle='#394653';c.font='22px sans-serif';c.textAlign='center';c.fillText('يُجهَّز مشهد المغامرة…',480,200);return;}
 c.textAlign='center';const ground=350;
 adventureStars.forEach((s,i)=>{if(!adventureCollected.has(i))adventureGoldStar(c,s.x,s.y-24,15,now);});
 if(oralCurrent){const x=adventureGate();adventureShadow(c,x+55,ground,30);adventureDrawCompanion(c,oralStep().speaker,x+55,ground);c.save();c.fillStyle='rgba(255,255,255,.92)';c.beginPath();c.roundRect(x-45,ground-210,180,37,16);c.fill();c.fillStyle='#5a3245';c.font='bold 18px sans-serif';c.fillText('تحدّثي مع '+oralStep().speaker,x+45,ground-185);c.restore();if(adventureTalking){const glow=c.createRadialGradient(x-34,ground,0,x-34,ground,35);glow.addColorStop(0,'rgba(102,204,199,.65)');glow.addColorStop(1,'rgba(102,204,199,0)');c.fillStyle=glow;c.fillRect(x-69,ground-25,70,40);}}
 else{adventureGoldStar(c,894,ground-68,38,now);c.fillStyle='#593a26';c.font='bold 22px sans-serif';c.fillText('أحسنتِ!',894,ground-12);}
 adventureShadow(c,adventureX,ground,24);let frame=adventureY<323?2:adventureMove&&Math.floor(now/180)%2?1:0;adventureDrawPerson(c,frame,adventureX,adventureY+26,160,adventureMove<0);
}



