function writingNormalize(t){return String(t).normalize('NFKC').replace(/[\u064B-\u065F\u0670\u0640]/g,'').replace(/[أإآ]/g,'ا').replace(/[.,،!؟?:؛]/g,' ').replace(/\s+/g,' ').trim();}
function writingMatches(t,expected){return writingNormalize(t)===writingNormalize(expected);}
function writingSentenceReview(t,word){const words=writingNormalize(t).split(' ').filter(Boolean);return{enough:words.length>=2&&!["في","على","إلى","من","عن","هذا","هذه","الذي","التي"].map(writingNormalize).includes(words.at(-1)),uses:words.includes(writingNormalize(word)),punctuation:/[.!؟]$/.test(t.trim())};}

const writingLastShuffle=new Map();
function writingShuffleWords(question,random=Math.random){
 const indices=question.words.map((_,i)=>i),key=question.words.join('|'),previous=writingLastShuffle.get(key);
 const answers=(question.accepted||[question.words.join(' ')]).map(writingNormalize);
 const solved=order=>answers.includes(writingNormalize(order.map(i=>question.words[i]).join(' ')));
 const candidates=[],fallback=[];
 function permute(prefix,remaining){if(!remaining.length){if(!solved(prefix)){fallback.push(prefix);if(prefix.length<3||!solved([...prefix].reverse()))candidates.push(prefix);}return;}for(const index of remaining)permute([...prefix,index],remaining.filter(i=>i!==index));}
 // Short activities use at most five words. Choose among all genuinely mixed orders.
 if(indices.length<=7)permute([],indices);
 if(!candidates.length)candidates.push(...fallback);
 let options=candidates.filter(order=>order.join(',')!==previous);
 if(!options.length)options=candidates;
 let result;
 if(options.length)result=options[Math.min(options.length-1,Math.floor(random()*options.length))];
 else{result=[...indices];for(let i=result.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}}
 writingLastShuffle.set(key,result.join(','));return result;
}

