function wProgress(){const counts=[1,writingData.choices.length,writingData.blanks.length,writingData.orders.length,writingData.writes.length,1],stars=counts.filter((n,i)=>Array.from({length:n},(_,j)=>`${i}-${j}`).every(id=>writingSaved.done.includes(id))).length;$('writingProgress').textContent='⭐ '+stars+' / ٦ خطوات مكتملة · يمكنكِ المحاولة دون خسارة نجوم.';document.querySelectorAll('#writingSteps button').forEach((b,i)=>{b.classList.toggle('writingDone',Array.from({length:counts[i]},(_,j)=>`${i}-${j}`).every(id=>writingSaved.done.includes(id)));});}
