let studentProfile=null;
try{studentProfile=JSON.parse(localStorage.getItem('arabic-student-profile-v1')||'null');}catch{}
function studentTotals(){let speaking=0;for(const p of Object.values(oralSaved.places||{})){speaking+=Object.values(p.activities||{}).filter(a=>a.firstStar).length+(Number(p.groups)||0)+(p.badge?1:0);}const counts=[1,writingData.choices.length,writingData.blanks.length,writingData.orders.length,writingData.writes.length,1];const writing=counts.filter((n,i)=>Array.from({length:n},(_,j)=>`${i}-${j}`).every(id=>writingSaved.done.includes(id))).length;return{speaking,writing};}
function studentResult(){const t=studentTotals(),b=studentProfile?.baseline||{speaking:0,writing:0};return{speaking:Math.max(0,t.speaking-b.speaking),writing:Math.max(0,t.writing-b.writing)};}
function refreshStudent(){const p=studentProfile,r=studentResult();$('studentStatus').textContent=p?`${p.role==='parent'?'وليّ أمر: ':'طالبة: '}${p.name} · ${p.grade} | ⭐ ${r.speaking+r.writing} نقطة — التحدث: ${r.speaking}، الكتابة: ${r.writing}`:'احفظي بياناتكِ أولًا لنحسب نقاطكِ من بداية هذه التجربة.';$('downloadStudentReport').disabled=!p;}
if(studentProfile){$('participantRole').value=studentProfile.role||'student';$('studentName').value=studentProfile.name||'';$('studentGrade').value=studentProfile.grade||'';}
$('studentForm').onsubmit=event=>{event.preventDefault();const role=$('participantRole').value,name=$('studentName').value.trim(),grade=$('studentGrade').value.trim();if(!name||!grade)return;const changed=studentProfile&&(role!==(studentProfile.role||'student')||name!==studentProfile.name||grade!==studentProfile.grade);if(changed){$('studentStatus').textContent='لتبديل الطالبة استخدمي «بدء طالبة جديدة». تعديل البيانات سيبدأ حسابًا جديدًا للنقاط.';return;}studentProfile={role,name,grade,baseline:studentProfile?.baseline||studentTotals(),started:studentProfile?.started||new Date().toISOString()};try{localStorage.setItem('arabic-student-profile-v1',JSON.stringify(studentProfile));}catch{$('studentStatus').textContent='تعذّر حفظ البيانات على الجهاز؛ نزّلي التقرير قبل إغلاق الصفحة.';return;}refreshStudent();};
$('studentNew').onclick=()=>{$('studentNewConfirm').hidden=false;};$('studentNewCancel').onclick=()=>{$('studentNewConfirm').hidden=true;};
$('studentNewYes').onclick=()=>{if(recording||pending||processing)return;studentProfile=null;oralSaved={version:1,places:{}};writingSaved={done:[]};try{localStorage.removeItem('arabic-student-profile-v1');localStorage.removeItem(oralStoreKey);localStorage.removeItem('hayya-writing-v1');}catch{}$('studentForm').reset();$('studentNewConfirm').hidden=true;refreshStudent();};
function studentCsvCell(value){let s=String(value??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
$('downloadStudentReport').onclick=()=>{if(!studentProfile)return;const r=studentResult(),rows=[['نوع المشارك','اسم المشارك','الصف','نقاط التحدث','نقاط الكتابة','مجموع النقاط','بداية التدريب','تاريخ التقرير'],[studentProfile.role==='parent'?'ولي أمر':'طالبة',studentProfile.name,studentProfile.grade,r.speaking,r.writing,r.speaking+r.writing,studentProfile.started,new Date().toISOString()]],blob=new Blob(['\ufeff'+rows.map(row=>row.map(studentCsvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='نتيجة-الطالبة.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1500);};
