const resultsConfig={"url":"https://uwevxjtgurkwotitxtac.supabase.co","publishableKey":"sb_publishable_ugT8zyGJGwEyEcjBwNNOtg_uUN5ukSS"};
let resultSending=false;
function cloudResultPayload(profile,points){if(!profile||![profile.name,profile.grade].every(x=>typeof x==='string'&&x.trim()))throw Error('بيانات الطالبة غير مكتملة.');if(!Number.isInteger(points.speaking)||points.speaking<0||points.speaking>1000||!Number.isInteger(points.writing)||points.writing<0||points.writing>66)throw Error('تعذّر التحقق من النقاط.');return {student_name:(profile.role==='parent'?'ولي أمر: ':'')+profile.name.trim(),student_class:profile.grade.trim(),teacher_name:'غير محددة',speaking_points:points.speaking,writing_points:points.writing,training_started_at:profile.started};}
async function sendCloudResult(config,payload,fetcher=fetch){if(!/^https:\/\/[a-z0-9]+\.supabase\.co$/.test(config.url)||!config.publishableKey.startsWith('sb_publishable_'))throw Error('إعداد ربط النتائج غير مكتمل.');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const response=await fetcher(config.url+'/rest/v1/student_results',{method:'POST',headers:{apikey:config.publishableKey,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(payload),signal:controller.signal});if(!response.ok){const messages={400:'تعذّر قبول البيانات. راجعي بطاقة الطالبة.',401:'تعذّر الاتصال بالمشروع. يحتاج مفتاح الربط إلى مراجعة.',403:'لم يُسمح بحفظ النتيجة. تحتاج صلاحيات الجدول إلى مراجعة.',404:'جدول النتائج غير متاح. يحتاج إعداد المشروع إلى مراجعة.',429:'الخدمة مشغولة. حاولي لاحقًا.'};throw Error(messages[response.status]||'تعذّر حفظ النتيجة في الخدمة.');}return true;}finally{clearTimeout(timer);}}
function refreshCloudButton(){const button=$('sendStudentResult');if(!button)return;button.disabled=resultSending||!studentProfile||!resultsConfig.url;}
$('sendStudentResult').onclick=async()=>{if(resultSending||!studentProfile)return;const profile=studentProfile,payload=cloudResultPayload(profile,studentResult()),signature=JSON.stringify(payload);if(profile.lastSent===signature){$('cloudResultStatus').textContent='أرسلتِ هذه النتيجة بالفعل. تدربي أكثر لإرسال نتيجة جديدة.';return;}resultSending=true;refreshCloudButton();$('cloudResultStatus').textContent='جارٍ إرسال النتيجة…';try{await sendCloudResult(resultsConfig,payload);profile.lastSent=signature;try{localStorage.setItem('arabic-student-profile-v1',JSON.stringify(profile));}catch{}$('cloudResultStatus').textContent='✓ وصلت نتيجتكِ إلى جدول المعلمة.';}catch(error){$('cloudResultStatus').textContent=error.name==='AbortError'?'لم نتأكد من وصول النتيجة بسبب تأخر الاتصال. تحققي مع المعلمة قبل إعادة الإرسال.':error instanceof TypeError?'تعذّر الاتصال بالإنترنت؛ بياناتكِ محفوظة على الجهاز.':error.message;}finally{resultSending=false;refreshCloudButton();}};
const studentRefreshWithoutCloud=refreshStudent;refreshStudent=function(){studentRefreshWithoutCloud();refreshCloudButton();};
const profileSubmitWithoutCloud=$('studentForm').onsubmit;$('studentForm').onsubmit=event=>{const sent=studentProfile?.lastSent;profileSubmitWithoutCloud(event);if(sent&&studentProfile){studentProfile.lastSent=sent;try{localStorage.setItem('arabic-student-profile-v1',JSON.stringify(studentProfile));}catch{}}};
const sendWithoutErrorBoundary=$('sendStudentResult').onclick;$('sendStudentResult').onclick=async()=>{try{await sendWithoutErrorBoundary();}catch(error){$('cloudResultStatus').textContent=error.message;}};
const newStudentWithoutCloud=$('studentNewYes').onclick;$('studentNewYes').onclick=()=>{if(resultSending)return;newStudentWithoutCloud();$('cloudResultStatus').textContent='';};
$('studentNew').addEventListener('click',()=>{if(resultSending){$('studentNewConfirm').hidden=true;$('cloudResultStatus').textContent='انتظري انتهاء إرسال النتيجة قبل تبديل الطالبة.';}});
refreshCloudButton();

