function writingStageDone(step){return Array.from({length:writingStageCounts()[step]},(_,i)=>`${step}-${i}`).every(id=>writingSaved.done.includes(id));}
function writingStageOpen(step){return step===0||Array.from({length:step},(_,i)=>i).every(writingStageDone);}
