if(step>0){const cards=Array.from(tasks.querySelectorAll(':scope > .writingTask'));const active=cards.findIndex((_,i)=>!writingSaved.done.includes(`${step}-${i}`));cards.forEach((card,i)=>card.hidden=stageDone||i!==active);if(stageDone&&step>=4&&writingDrafts[step]){cards[0].hidden=false;cards[0].querySelectorAll('textarea').forEach((input,i)=>input.value=writingDrafts[step][i]||'');}}
if(writingReward){const reward=wElement('p',writingReward,'writingReward');reward.setAttribute('role','status');tasks.insertBefore(reward,journey.nextSibling);writingReward='';}
if(stageDone){const win=wElement('section',null,'writingWin');win.append(wElement('div',step===5?'🏆':'⭐','writingWinIcon'),wElement('h3',step===5?'أحسنتِ! أكملتِ رحلة حروف الجر':'جمعتِ نجمة هذه المرحلة!'),wElement('p',step===5?'ست نجوم، وست مراحل. اعرضي جملتيكِ على معلمتكِ.':'المحاولة جزء من التعلم. المرحلة التالية أصبحت مفتوحة.'),wButton(step===5?'🏙 أعود إلى مدينة الكلمات':'🚂 إلى المرحلة التالية',()=>{if(step===5){$('writingTrain').hidden=true;$('writingLobby').hidden=false;}else drawWriting(step+1);}));tasks.append(win);}
