const completeWithoutAdventure=wComplete;wComplete=function(id){const wasDone=writingSaved.done.includes(id);if(writingStep>=4)writingDrafts[writingStep]=Array.from($('writingTasks').querySelectorAll('textarea')).map(input=>input.value);completeWithoutAdventure(id);if(!wasDone){writingReward=writingStageDone(writingStep)?(writingStep===5?'✨ أحسنتِ! جمعتِ نجوم الرحلة الست.':'✨ أحسنتِ! نجمة جديدة، ومرحلة جديدة مفتوحة.'):'✨ أحسنتِ! اقتربتِ من نجمة المرحلة.';drawWriting(writingStep);}};
