const summaryBeforeLevels=renderOralSummary;renderOralSummary=function(){summaryBeforeLevels();const name={1:'أكرر',2:'أتحاور'}[oralLevel],activities=oralBank().activities.filter(a=>a.level===Number(oralLevel)),completed=activities.filter(a=>oralStat(a.id).done).length;const complete=completed===activities.length;$('oralSummaryTitle').textContent=complete?'⭐ أحسنتِ! أكملتِ مستوى «'+name+'»':'🌱 نواصل التدريب في «'+name+'»';$('oralSummaryText').textContent=`${completed} / ${activities.length} أنشطة مكتملة في هذا المستوى · ⭐ ${oralTotals().stars} نجوم في هذا المكان`;levelNext.hidden=!complete||oralLevel==='3';levelNext.textContent='إلى المحطة الثانية · أتحاور';};

