function selectWritingChapter(i){writingChapterProgress[writingChapter]=writingSaved;writingChapter=i;Object.assign(writingData,writingBanks[i]);writingSaved=writingChapterProgress[i]||{done:[]};writingChapterProgress[i]=writingSaved;writingDrafts={};writingReward='';$('writingTrain').querySelector('h3').textContent=writingData.title;}
