const writeMatchLoose=writingMatches;writingMatches=function(t,e){if(writingChapter===6||writingChapter===10)return String(t).normalize('NFKC').replace(/[\u064B-\u065F\u0670\u0640]/g,'').trim()===String(e).normalize('NFKC').replace(/[\u064B-\u065F\u0670\u0640]/g,'').trim();const alternatives={جميل:['جميل','رائع','جديد','مفيد','ممتع','كبير','صغير','نظيف'],جميلة:['جميلة','رائعة','جديدة','مفيدة','ممتعة','كبيرة','صغيرة','نظيفة'],مشرقة:['مشرقة','ساطعة','دافئة'],اللاتي:['اللاتي','اللائي']};if(alternatives[e])return alternatives[e].some(a=>writeMatchLoose(t,a));return writeMatchLoose(t,e);};
function wordSound(word){return writingWordSounds[word]||word;}
function illustratedWord(word,group='',example=''){return discoverIllustration(word,group,example);}
function fullWritingDiscover(){const info=skillInfographics[writingChapter],root=wElement('section',null,'discoverGraphic');root.append(wElement('h3',info.title),wElement('p',info.idea,'writingRule'),wButton('🔊 استمعي للشرح مع مثال',()=>say(writingBanks[writingChapter].instruction)));info.groups.forEach(group=>{root.append(wElement('h4',group.title));const grid=wElement('div',null,'discoverGrid');group.items.forEach(item=>{const tile=wElement('article',null,'discoverTile');tile.append(illustratedWord(item.word,group.title,item.example||''),wButton('🔊 '+item.word,()=>say(wordSound(item.word))));if(item.example)tile.append(wElement('p',item.example,'discoverExample'),wButton('🔊 اسمعي المثال',()=>say(item.example)));grid.append(tile);});root.append(grid);});return root;}
showReference=function(i){selectWritingChapter(i);$('writingLobby').hidden=true;$('writingTrain').hidden=true;$('writingReference').hidden=false;$('referenceContent').replaceChildren(fullWritingDiscover());if(i===0)$('referenceContent').append(writingVideoCard());$('referenceTrain').hidden=false;$('referenceTrain').textContent='⭐ أبدأ رحلة '+writingData.title;$('referenceNotice').textContent='ست مراحل قصيرة. التحدي الأخير: جملتان عن الصورة.';};
function writingInstruction(step){const bank=writingBanks[writingChapter],model=bank.examples[0].sentence;return step===0?bank.instruction:['',`اختاري الكلمة المناسبة. مثال: ${model}`,`أكملي الفراغ. مثال: ${model}`,`رتبي الكلمات لتصنعي جملة. مثال: ${model}`,`اكتبي جملة واحدة عن الصورة باستخدام المهارة. مثال: ${model}`,`اكتبي جملتين فقط عن الصورة. مثال لجملة واحدة: ${model}`][step];}
const writingAdventureDraw=drawWriting;drawWriting=function(step){writingAdventureDraw(step);step=writingStep;const tasks=$('writingTasks');const instructionButton=Array.from(tasks.children).find(e=>e.tagName==='BUTTON'&&e.textContent.includes('تعليمات'));if(instructionButton)instructionButton.onclick=()=>say(writingInstruction(step));if(step===0){const graphic=tasks.querySelector('.discoverGraphic');if(graphic)graphic.replaceWith(fullWritingDiscover());if(writingChapter!==0)tasks.querySelector('.writingVideoCard')?.remove();}const win=tasks.querySelector('.writingWin h3');if(win&&step===5)win.textContent='أحسنتِ! أكملتِ '+writingData.title;
if(writingChapter!==0&&step>=4){tasks.querySelectorAll(':scope > .writingTask').forEach(e=>e.remove());const card=wTask();card.hidden=writingStageDone(step)&&!writingDrafts[step];card.append(illustratedWord(writingData.targets.join(' · ')),wElement('p',step===4?'اكتبي جملة واحدة عن المشهد باستخدام المهارة.':'اكتبي جملتين عن المشهد باستخدام المهارة.'),wElement('p','في ساحة المدرسة: طالبات يحملن الكتب والحقائب، ومعلمة تقف قرب الباب.'));const image=document.createElement('img');image.src=writingArt.challenge;image.alt='مشهد الطالبات والكتب في ساحة المدرسة';card.append(image);const inputs=[];for(let j=0;j<(step===4?1:2);j++){const input=document.createElement('textarea');input.setAttribute('aria-label','جملتي '+(j+1));input.value=writingDrafts[step]?.[j]||'';card.append(input);inputs.push(input);}const out=document.createElement('output');card.append(wButton('راجعي جملتي',()=>{const valid=inputs.every(t=>writingNormalize(t.value).split(' ').filter(Boolean).length>=2&&writingSkillUsed(t.value));out.textContent=valid?'⭐ أحسنتِ! أتممتِ الكتابة. اعرضي الجمل على معلمتكِ لمراجعة المعنى وصحة استخدام المهارة.':'🌱 اكتبي جملة قصيرة من كلمتين على الأقل واستخدمي المهارة. يمكنكِ الاستماع إلى المثال.';if(valid)wComplete(step+'-0');}),out);tasks.append(card);}
if(step===2&&writingChapter!==0){tasks.querySelectorAll('input').forEach((input,i)=>input.setAttribute('aria-label','الكلمة أو العلامة للجملة '+(i+1)));const p=Array.from(tasks.children).find(e=>e.tagName==='P'&&e.textContent.includes('اختاري حرف'));if(p)p.textContent='أكملي الفراغ بالكلمة أو العلامة المناسبة.';}
tasks.querySelectorAll('.writingTask').forEach((card,i)=>{if(step===1){if(writingChapter!==0)card.prepend(illustratedWord(writingData.choices[i].answer));card.querySelectorAll('button').forEach(b=>{const original=b.onclick;b.onclick=()=>{say(wordSound(b.textContent));original();};});}card.querySelectorAll('.wordBank button,.sentenceTrain button').forEach(b=>{const prev=b.onclick;b.onclick=()=>{say(wordSound(b.textContent));prev();};});});};
function writingSkillUsed(text){const clean=writingNormalize(text),words=clean.split(' ').filter(Boolean);if(writingChapter===10)return /[.؟!،:؛]/.test(text);if(writingChapter===3)return /[تة](?:\s|[.؟!،]|$)/.test(text);if(writingChapter===4)return /(?:^|\s)ال[^\s]+/.test(clean);if(writingChapter===6)return /(?:^|\s)[أإا]\S+/.test(text);if(writingChapter===5)return words.some(w=>/^(?:ب|ل|ك|ف)ال.+/.test(w));if(writingChapter===7)return words.some(w=>['هذا','هذه','ذلك','تلك'].includes(w))||/[ة](?:\s|[.؟!،]|$)/.test(text);if(writingChapter===8)return words.some(w=>/ان$|ين$|ات$/.test(w)||['كتاب','قلم','طالبة','كتب','أقلام','طالبات','طلاب','بنات'].map(writingNormalize).includes(w));const fullWords=skillInfographics[writingChapter].groups.flatMap(g=>g.items.flatMap(item=>item.word.split('/').map(x=>writingNormalize(x.trim()))));return [...writingData.targets.map(writingNormalize),...fullWords].some(w=>words.includes(w));}
