const oldStudentTotals=studentTotals;studentTotals=function(){const totals=oldStudentTotals();writingChapterProgress[writingChapter]=writingSaved;totals.writing=writingBanks.reduce((sum,b,i)=>{const progress=writingChapterProgress[i]?.done||[],counts=[1,b.choices.length,b.blanks.length,b.orders.length,b.writes.length,1];return sum+counts.filter((n,s)=>Array.from({length:n},(_,j)=>`${s}-${j}`).every(id=>progress.includes(id))).length;},0);return totals;};
