function studentReady(){return !!studentProfile&&['name','grade'].every(k=>typeof studentProfile[k]==='string'&&studentProfile[k].trim().length>0);}
let pendingStudentStart=null;
function requireStudent(start){if(studentReady())return true;pendingStudentStart=start||null;showWorldHome();studentGateNotice.textContent='قبل أن تبدئي: أدخلي الاسم الأول، وصف الطالبة، ثم اضغطي حفظ البيانات.';const card=$('studentForm').closest('.studentCard');card.classList.add('studentRequired');card.scrollIntoView({behavior:'smooth',block:'center'});const missing=['studentName','studentGrade'].find(id=>!$(id).value.trim());$(missing||'studentName').focus({preventScroll:true});return false;}
const speakingWithCard=$('speakingMode').onclick;$('speakingMode').onclick=()=>{if(requireStudent(()=>$('speakingMode').click()))speakingWithCard();};
const writingWithCard=$('writingMode').onclick;$('writingMode').onclick=()=>{if(requireStudent(()=>$('writingMode').click()))writingWithCard();};
const openPlaceWithCard=openPlace;openPlace=function(i){if(requireStudent(()=>openPlace(i)))openPlaceWithCard(i);};
const drawWritingWithCard=drawWriting;drawWriting=function(step){if(requireStudent(()=>{$('learningModes').hidden=true;$('writingCity').hidden=false;$('writingLobby').hidden=true;$('writingReference').hidden=true;$('writingTrain').hidden=false;drawWriting(step);}))drawWritingWithCard(step);};
const saveStudentWithGate=$('studentForm').onsubmit;$('studentForm').onsubmit=event=>{saveStudentWithGate(event);if(studentReady()){studentGateNotice.textContent='';$('studentForm').closest('.studentCard').classList.remove('studentRequired');const start=pendingStudentStart;pendingStudentStart=null;if(start)start();}};
const resetStudentWithGate=$('studentNewYes').onclick;$('studentNewYes').onclick=()=>{resetStudentWithGate();if(!studentReady()){pendingStudentStart=null;showWorldHome();}};
$('studentForm').prepend(wElement('p','هذه البيانات مطلوبة قبل بدء التحدث أو الكتابة.','studentRequiredNote'));

const participantRole=$('participantRole');function showParticipantLabels(){const parent=participantRole.value==='parent';$('studentName').maxLength=parent?32:40;[['studentName',parent?'اسم وليّ الأمر الأول':'اسم الطالبة الأول'],['studentGrade',parent?'صف الطالبة':'الصف']].forEach(([id,title])=>{const label=$(id).closest('label');label.firstChild.textContent=title;});$('studentForm').querySelector('.studentRequiredNote').textContent=parent?'وليّ الأمر مرحّب به! أدخل اسمك الأول وصف الطالبة.':'هذه البيانات مطلوبة قبل بدء التحدث أو الكتابة.';}participantRole.onchange=showParticipantLabels;showParticipantLabels();
